from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_field_objects import Xvi_field_page
from interops.libraries.xvi.interactions.objects.xvi_treatment_objects import Xvi_Treatment_page
from ..interactions import new_field_reg


def enter_field_details(fieldID: str, fieldDescription: str ,fieldSite:str) -> None:
    """Enter all basic details on the New treatment window
    fieldID=,fieldDescription,fieldSite
    """
    new_field_reg.open_field_newPage()
    new_field_reg.typeText_in_field_id(fieldID)
    new_field_reg.typeText_in_field_description(fieldDescription)
    new_field_reg.typeText_in_field_site(fieldSite)
    new_field_reg.select_inactive()
    new_field_reg.clickOK()
